#!/bin/bash
# Headless QEMU boot tests for the Forge OS demos. Prints PASS/FAIL lines like run_tests.sh.
#   1. kernel via GRUB multiboot2, legacy BIOS (SeaBIOS)
#   2. same hybrid ISO via GRUB x86_64-efi under OVMF (UEFI)
#   3. native Forge UEFI loader (\EFI\Forge\forgex64.efi) from the ESP of a GPT disk shared with
#      Windows/Linux partitions: reads \EFI\Forge\kernel.elf, GOP, ExitBootServices, jumps to the kernel
# Every path must reach KERNEL OK with the same checks, and the framebuffer text is
# decoded from a QEMU screendump (tests/os/boot.py): the (scrolled) framebuffer console must show KERNEL OK.
cd "$(dirname "$0")/../.."
OVMF_CODE=${OVMF_CODE:-/usr/share/OVMF/OVMF_CODE_4M.fd}
OVMF_VARS=${OVMF_VARS:-/usr/share/OVMF/OVMF_VARS_4M.fd}
Q="-cpu max -display none -no-reboot -net none -m 256 -smp 4 -serial stdio -device isa-debug-exit,iobase=0xf4,iosize=0x04"
examples/kernel/build.sh >/dev/null || { echo "FAIL os/kernel-build"; exit 0; }
examples/efi/build.sh >/dev/null || { echo "FAIL os/efi-build"; exit 0; }
L=build/os; mkdir -p $L
readelf -lW build/kernel/kernel.elf | grep -q "LOAD.* RWE " && echo "FAIL os/kernel-wx (RWX PT_LOAD)" || echo "PASS os/kernel-wx (no RWX PT_LOAD)"
FB="back == front^KERNEL OK"
BIGH=$(python3 -c "
h=0xcbf29ce484222325
for i in range(98304): h=((h^((i*7+(i>>9))&255))*0x100000001b3)&(2**64-1)
print('%016x'%h)")
K="badptr: PASS|[badptr exited 0]|user ELF bounds: 5 malformed headers|uaccess: 9 kernel-pointer probes -> EFAULT|fb console: double-buffered |), back == front|per-CPU run queues: |HPET: period |TSC-deadline timer: |verify: /efi/forge/bin/unsealed refused: no proof manifest|verify: /efi/forge/bin/tampered refused: image hash mismatch|verify: /efi/forge/bin/forged refused: bad manifest signature|verify: /efi/forge/bin/linuxabi refused: Linux ABI image needs the compatibility sandbox|linux: Linux ABI personality ready (17 syscalls), only for sealed images launched in the compat sandbox|verify: /efi/forge/bin/lxtest refused: Linux ABI image needs the compatibility sandbox|under the Linux ABI personality (compat sandbox), argc 1|lxtest: auxv 9 entries, AT_PAGESZ 4096, AT_ENTRY ok 1, AT_SECURE 0, AT_RANDOM 16 bytes 1|lxtest: brk +12288 ok, mmap 8192 ok, PROT_EXEC -> EACCES, MAP_FIXED -> EINVAL|lxtest: TLS %fs:0 = self ok, 400 yields, bad reads 0|registers preserved, syscall 409 -> ENOSYS|lxtest: PASS (|[lxtest exited 0 (sandboxed)]|lxthreads: 4 threads joined via CLONE_CHILD_CLEARTID + FUTEX_WAIT, counter 8000 (expected 8000)|lxthreads: per-thread TLS ok (bad reads 0), gettid distinct, getpid shared|lxthreads: futex EAGAIN/EINVAL ok, clone(fork) -> ENOSYS|lxthreads: spinner and sleeper running; exit_group must end both|lxthreads: PASS (10 checks)|finished: 6 threads created, all joined and freed; futex waits |[lxthreads exited 0 (sandboxed)]|syscall 409 not supported -> ENOSYS|[capdeny exited 0]|proof manifest (Ed25519): 3 sealed images accepted|capdeny: open allowed, fork denied, probe denied|capability gate: undeclared spawn and probe denied at the syscall boundary|identity 0x0000000000100000 -> unmapped|stack guard 0xffffffffc002f000 -> unmapped|breakpoints handled: 2|live=0|buddy: orders 0..10 aligned (bad 0)|buddy allocator OK|vmalloc VA reuse OK|; slot bookkeeping OK|demand paging: 3 faults|MADT: cpus=|memory reclaimed: |#DF on IST1|recovered from #DF|LAPIC timer ticks: 20|PIT IRQ0 via IOAPIC gsi 2: |CPU: FPU state |SMEP on, SMAP on|unmapped ptr -> 14, kernel ptr -> 14|SMAP blocks kernel read: 1, SMEP blocks kernel exec: 1|xmm0-15 intact after 20 yields|all cpus see the new frame: yes|6 threads x 2000 increments = 12000|checksum ok|wait queues + sleeping mutexes + condvars OK|Vec/Map on the kernel heap: sum 1498500, map len 250, heap leaked 0|generic Vec/Map OK|captest: read-only handle: write denied, widening denied|captest: dir capability: relative lookup ok|captest: child with only a read-only handle: write denied, no ambient path lookup|captest: PASS|chantest: ping-pong 2000 round trips in|chantest: handle moved over the channel; receiver read it, write denied, XFER enforced|chantest: peer close gives EOF|chantest: PASS|sh: run sbtest: 2 grants from its manifest|) runs with 2 manifest handles, no root capability|(sbtest) denied open /efi/forge/bin/cat: not in its manifest|(sbtest) denied exec /efi/forge/bin/hello: not in its manifest|sbtest: manifest handles work|sbtest: access outside the manifest denied (open, stat, exec)|sbtest: PASS|sh: run grtest: 1 grants from its manifest|[grtest started in the background (sandboxed), pid |grants: grant |(grtest: read /efi/forge/docs/big.bin) active for pid |grtest: halfway, 49152 of 98304 bytes read through grant fd 4|(grtest: read /efi/forge/docs/big.bin) from pid |sh: revoked 1 grant(s) of grtest|(grtest: read /efi/forge/docs/big.bin): revoked; pid |grtest: cut off mid-read at byte 49152: read, read on the earlier dup, and dup all return EACCES|grants: ledger, | revoked, |audit: | records, 0 evicted|: granted to sbtest, /efi/forge/docs|: granted to grtest, /efi/forge/docs/big.bin|: read x12, 49152 bytes|: openat x1|: revoked by pid |: poll denied x1|: read denied x2|: dup denied x1|: ended (app exited)|audit: ledger check: uses and denials match the ledger for all 3 grants|user W^X: RWX segment refused, mixed RX/RW page refused|wxtest: exec data/mmap/stack and write text all killed by #PF|wxtest: PASS|[wxtest exited 0]|[sbtest exited 0 (sandboxed)]|denied exec (no root capability)|SMP: 4 cpus online|cpus used 4/4|preemptive SMP scheduler OK|x2APIC: all cpus in x2APIC mode, IPIs sent via MSR 0x830: |x2APIC mode, LAPIC id=|KASLR: big heap at 0xffffc0|overflowed its stack into the guard page: killed, kernel carries on|kernel stack guard pages: overflowing thread killed, stack frames returned|smashed its frame, caught before return: killed|stack canaries: overflow past a local buffer detected, thread killed, kernel carries on|cpl 3|-> killed|frames leaked 0, heap leaked 0|ring 3 + syscall/sysret + ELF loader OK|virtio-blk (transitional)|MSI-X vector 0x50 -> cpu0, sleeping requests| MSI-X completions, |read-only|FAT32: ESP at LBA 2048|init.elf(|identical to the build output|from disk exited with|PCI + virtio-blk + FAT32 (read-only) OK|module hello.ko: |hello from a loaded module, calls=2|state restored|1000 load/call/unload cycles in |frames leaked 0, heap bytes leaked 0|rejected truncated hello.ko: |rejected badabi.ko: ABI version mismatch|rejected unresolved.ko: unresolved symbol (kernel_secret_internal)|rejected newer.ko: import newer than the module ABI (kabi_future_probe)|module ABI OK: 1002 loads, 1002 unloads, 7 rejected|rejected unsealed.ko: no proof manifest|rejected tampered.ko: image hash mismatch|rejected userimg.ko: wrong image kind|tty hot-swap: unsealed tty1u.ko refused, current line discipline kept|blkd: pid |through the user-mode driver, identical; |blkd crashed (exit 0x000000000000010e), client got EIO and is still running; device reset, deaths=1|blkd: frames leaked 0, heap leaked 0|isolated driver service OK|Forge sh: builtins|sh$ ls|forktest  |forktest: fork ok|5 children reaped, ECHILD|mmap 16KiB rw ok|hello: args = 'from-exec 1 2 3'|forktest: PASS|It spans more than one 13-character LFN entry|[cat exited 0]|hello: args = 'a b'|sh: nosuch: command not found|[nosuch exited 127]|docs/|sh: bye|sh exited with 0|shell session: frames leaked 0, heap leaked 0|processes + VFS + keyboard/serial input + sh OK|crash: block driver will die on request 40|supervisor: blkd (pid |, restart 1, replaying request |pages, restart 1|sum: 98304 bytes fnv1a64=$BIGH|supervisor: blkd restarts 1, |supervised driver restart OK| with a partial line queued), pushed |, lost 0|tty hot-swap OK|crash: input driver will die on the batch holding entry 4|input supervisor: kbdd v|, restart 1, replaying from entry |hello: args = 'Swap OK'|input service: lost 0|input service hot-swap + supervised restart OK|livepatch: sys_getpid patched + reverted 25 times on 4 CPUs, stop-machine parked 3 CPUs per write| through the patch), wrong 0|livepatch: 2 sites (sys_getpid, sys_getppid) patched independently, both live in 25 rounds, |livepatch: bad patch rejected before install (rejects 2), failed patch rolled back (rollbacks 1), text hash restored, frames leaked 0, heap leaked 0|live patching OK|KERNEL OK|kernel version: forge-kernel 0.2.6|[bg started in the background, pid |bg: pid | read 49152 bytes, waiting for kernel generation 1|kexec: generation 1 kernel (kernel-next.elf) loaded at | processes, |KiB handoff region (format v4), nothing written to disk|kernel version: forge-kernel 0.2.6-next|kexec handoff from the previous kernel (generation 1)|kexec: handoff format v4 from forge-kernel 0.2.6 (this kernel, forge-kernel 0.2.6-next, adopts v4..v4)|kernel adopted |hashes ok; handoff region|sh: survived kexec: |commands remembered, pid now|hello: args = 'after kexec'| in generation 1: 98304 bytes through the carried fd, hash matches a fresh read, heap words bad 0|[pid |running forge-kernel 0.2.6-next|kexec: input service state carried: kbdd v| 2 uncommitted entries, |carried entries replayed by the new driver: yes|driver state carried across kexec OK|kexec handoff OK"
B=tests/os/boot.py
# every path also gets the GPT disk as a read-only virtio-blk data disk (removable-media fallback loader
# deleted so firmware never boots from it); the kernel reads \EFI\Forge\init.elf from its ESP
cp build/efi/disk.img $L/vdisk.img && mdel -i $L/vdisk.img@@1048576 ::/EFI/BOOT/BOOTX64.EFI
VD="-drive file=$L/vdisk.img,format=raw,if=none,id=vd,readonly=on -device virtio-blk-pci,drive=vd"
python3 $B kernel-bios $L/bios.log 150 "multiboot2 (BIOS)|$K" "$FB" -- $Q $VD -boot d -cdrom build/kernel/forge.iso
# single CPU (-machine pc -smp 1): no APs, no IPIs; the kernel must still boot to KERNEL OK and kexec
Q1=${Q/-smp 4/-smp 1}
python3 $B kernel-bios-smp1 $L/bios-smp1.log 200 "SMP: 1 cpus online|x2APIC: all cpus in x2APIC mode, IPIs sent via MSR 0x830: 0|preemptive SMP scheduler OK|ring 3 + syscall/sysret + ELF loader OK|processes + VFS + keyboard/serial input + sh OK|KERNEL OK|kexec handoff OK" "$FB" -- $Q1 -machine pc $VD -boot d -cdrom build/kernel/forge.iso
cp $OVMF_VARS $L/vars.fd
UEFI="-machine q35 -drive if=pflash,format=raw,readonly=on,file=$OVMF_CODE -drive if=pflash,format=raw,file=$L/vars.fd"
python3 $B kernel-uefi $L/uefi.log 360 "multiboot2 (UEFI)|ACPI rev 2 XSDT|$K" "$FB" -- $Q $UEFI $VD -cdrom build/kernel/forge.iso
cp $OVMF_VARS $L/vars.fd
DH0=$(sha256sum < build/efi/disk.img)
python3 $B efi-loader-gpt $L/efi.log 360 "hello from PE32+|signature OK|, set mode |GOP 1024x768|exiting boot services|Forge UEFI loader (ExitBootServices done)|ACPI rev 2 XSDT|$K" "$FB" -- $Q $UEFI $VD -drive file=build/efi/disk.img,format=raw
# kexec handoff: the boot disk the loader ran from (writable in QEMU) is byte-identical afterwards
if [ "$(sha256sum < build/efi/disk.img)" = "$DH0" ]; then echo "PASS os/kexec-no-disk-write"; else echo "FAIL os/kexec-no-disk-write"; fi
python3 -c "import sys; k=open(\"build/user/seal.key\",\"rb\").read(); p=open(\"build/user/seal.pub\",\"rb\").read(); imgs=[open(f,\"rb\").read() for f in (\"build/kernel/kernel.elf\",\"build/efi/disk.img\")]; sys.exit(0 if all(k not in i and p in i for i in imgs) else 1)" && echo "PASS os/seal-private-key-not-shipped" || echo "FAIL os/seal-private-key-not-shipped"
# KASLR: every boot (3 first-generation kernels + 3 kexec'd ones) picks its own heap/stack bases
NK=$(grep -ah '^KASLR: big heap at' $L/bios.log $L/uefi.log $L/efi.log | sort -u | wc -l)
# image KASLR: each of the 6 kernels relocated itself to its own slide and unmapped the link-address alias;
# the UEFI loader and kexec both checked the image carries its relocation table
NI=$(grep -ah '^KASLR: kernel image at .*link-address alias unmapped' $L/bios.log $L/uefi.log $L/efi.log | sort -u | wc -l)
NU=$(grep -ah 'unslid .text 0x.* -> unmapped' $L/bios.log $L/uefi.log $L/efi.log | wc -l)
NL=$(grep -ah '^kernel relocatable: [1-9]' $L/efi.log | wc -l)
NX=$(grep -ah '^kexec: new kernel relocatable, [1-9]' $L/bios.log $L/uefi.log $L/efi.log | wc -l)
if [ "$NK" -ge 5 ] && [ "$NI" -ge 5 ] && [ "$NU" -eq 6 ] && [ "$NL" -eq 1 ] && [ "$NX" -eq 3 ]; then
    echo "PASS os/kaslr ($NK heap/stack layouts, $NI image bases in 6 boots)"
else echo "FAIL os/kaslr (layouts $NK, image bases $NI, unslid unmapped $NU, loader $NL, kexec $NX)"; fi

# Phase 8.7: hardware drivers on q35 (read-only disks, ARP only on restricted user netdevs)
bash tests/os/drivers.sh
# Phase 8.9: writable Forge FS on an explicitly created Forge partition only
bash tests/os/forgefs.sh

# Phase 7.3: -g kernel, DWARF line table, gdb breakpoint at schedule over the QEMU gdbstub
bash tests/dwarf/run.sh
